import{z as o,x,o as E,c as d,q as l,j as s,D as n,d as t,s as B,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"ext4 extent","description":"","frontmatter":{"title":"ext4 extent","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ext4-extents.md","filePath":"cs/ext4-extents.md","lastUpdated":1791063341000}'),p={name:"cs/ext4-extents.md"};function A(c,e,u,m,h,D){const i=x("Mermaid");return E(),d("div",null,[e[2]||(e[2]=l('<h1 id="ext4-extent" tabindex="-1">ext4 extent <a class="header-anchor" href="#ext4-extent" aria-label="Permalink to &quot;ext4 extent&quot;">​</a></h1><div class="epigraph"><p>extent 用「起始逻辑块、起始物理块、长度」描述一段连续分配，替换 inode 里那棵间接块树。</p><footer>—— 据 Mathur et al., The new ext4 filesystem, OLS 2007；Linux ext4 文档对 extent 树的整理</footer></div><p><a href="/cs/ext2-block-groups">上一课</a>把块指针放进 inode。大文件要多层间接块，元数据放大，顺序文件也被拆成百万个指针。<a href="/cs/ext4-journal">日志</a> 能捆更新，但不能把「一百万个块号」变短。缺口是 <strong>extent</strong>：连续区段，外加一棵小的索引树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>间接树的每个叶都是一个块号。1 TiB 文件、4 KiB 块，指针数量以亿计，inode 无法直接放下，读一个范围要先读多层间接块。缺口：一个 extent 覆盖最多 \\(2^{15}\\) 或实现所限的连续物理块（具体上限随内核版本），inode 内嵌几个 extent，溢出则变成 extent 树（内部索引结点指向叶）。逻辑空洞用「没有覆盖该逻辑块的 extent」表示，不必真分配。<span class="marginnote">术语翻译：extent 就是把「从盘上第 \\(z\\) 块起、连续 \\(y\\) 块都归我」写成一句话；原来这 \\(y\\) 块要一个指针一个指针地登记，现在一个「起点 + 长度」的三元组全部说完。</span></p><p>本课不把延迟分配的红黑树全部字段当课纲。</p><p><span class="marginnote">ext4 默认 extent；老 inode 仍可走间接块以兼容。<code>fallocate</code> 可预先插入 extent。与稀疏文件后课分工：这里先钉表示法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写扩展：分配器尽量返回连续物理块，合并进相邻 extent，否则插入新叶。树按逻辑块号排序，查找范围是一次树下降。截断：缩短最后一个 extent 或删叶，释放位图。对照 FAT：连续区段在 FAT 上仍是一段链，表项个数不减；extent 把链收成三元组。对照块组：分配仍优先本 <a href="/cs/ext2-block-groups">块组</a>，extent 只是记录结果的方式。</p>',9)),(E(),s(r,null,{default:n(()=>[B(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LBA%5B%22%E6%96%87%E4%BB%B6%E9%80%BB%E8%BE%91%E5%9D%97%22%5D%20--%3E%20TREE%5B%22extent%20%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20EXT%5B%22%E7%89%A9%E7%90%86%E8%B5%B7%E5%9D%80%E4%B8%8E%E9%95%BF%E5%BA%A6%22%5D%0A%20%20EXT%20--%3E%20DAT%5B%22%E8%BF%9E%E7%BB%AD%E7%9B%98%E5%9D%97%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[t("extent 把顺序工作负载的元数据从 \\(O(\\text{块数})\\) 降到 \\(O(\\text{段数})\\)。碎片仍会产生很多短 extent，于是有在线整理与分配策略，但对象不变：记录的是段，不是 FAT 项。日志仍写元数据块映像——extent 树结点也是元数据，"),a("a",{href:"/cs/ext4-journal"},"JBD2"),t(" 照样进事务。不要把 extent 当成数据库 B+ 树里的记录指针；叶上没有元组，只有块范围。")],-1)),e[5]||(e[5]=a("p",null,[t("与页缓存："),a("code",null,"readpage"),t(" 仍按页填，FS 用 extent 把页偏移译成盘地址，VFS 看不见树。")],-1)),(E(),s(r,null,{default:n(()=>[B(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20OLD%5B%22%E9%97%B4%E6%8E%A5%E5%9D%97%E6%A0%91%EF%BC%9Aext2%2F3%22%5D%0A%20%20%20%20B1%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%201%20TiB%20%E6%96%87%E4%BB%B6%22%5D%20--%3E%20B2%5B%22%E7%BA%A6%202.7%20%E4%BA%BF%E4%B8%AA%204%20KiB%20%E5%8F%B6%E6%8C%87%E9%92%88%22%5D%20--%3E%20B3%5B%22%E9%97%B4%E6%8E%A5%E5%9D%97%E6%9C%AC%E8%BA%AB%E5%8D%A0%E6%BB%A1%E5%A4%A7%E9%87%8F%E7%9B%98%E5%9D%97%22%5D%0A%20%20end%0A%20%20subgraph%20NEW%5B%22extent%20%E6%A0%91%EF%BC%9Aext4%22%5D%0A%20%20%20%20N1%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%201%20TiB%20%E6%96%87%E4%BB%B6%22%5D%20--%3E%20N2%5B%22%E7%BA%A6%208%20%E5%8D%83%E4%B8%AA%E4%B8%89%E5%85%83%E7%BB%84%EF%BC%88%E6%AF%8F%E6%AE%B5%E8%87%B3%E5%A4%9A%20128%20MiB%EF%BC%89%22%5D%20--%3E%20N3%5B%22%E4%B8%80%E5%B1%82%E5%8F%B6%E7%BB%93%E7%82%B9%E5%8D%B3%E5%8F%AF%E6%94%BE%E4%B8%8B%22%5D%0A%20%20end%0A"})]),fallback:n(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<p><span class="marginnote">数字实例：\\(1\\,\\text{TiB} = 2^{40}\\) 字节，\\(4\\,\\text{KiB}\\) 块即 \\(2^{12}\\)，相除得 \\(2^{28}\\approx 2.7\\) 亿个指针；换成 extent，每段最长 \\(2^{15}\\) 块 \\(=128\\,\\text{MiB}\\)，\\(1024\\,\\text{GiB}\\div 128\\,\\text{MiB}=8192\\) 段就够——元数据从「亿」缩到「千」。</span></p><p>实现上：extent 树的内部结点按逻辑块排序，插入可能分裂，于是一次追加写也会动多层元数据，仍要进 JBD2。bigalloc 把簇改成更大分配单元，是 extent 之上的另一层，本课不展开。 读法上只引用<a href="/cs/ext2-block-groups">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>ext4 extent</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 btrfs 的 B 树键空间，不把 bigalloc 簇写成另一文件系统。也不保证 extent 树在崩溃后无需日志——它替代的是间接块，不是崩溃协议。下一课把「原地改树」换成「永远追加日志」：LFS。<span class="marginnote">常见误区：初学者容易以为「换了 extent 就不怕断电」；extent 只是更紧凑的地址记法，树结点仍是原地改写的元数据，崩溃一致照样要靠 JBD2 日志兜底。</span></p><p>版本字段会变，课序钉的是机制对象「ext4 extent」，不是某一主线内核的结构体名。 后课默认：ext4 文件的块图是 extent。若每次写都追加而非改原地，布局会变成什么，下一课日志结构文件系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>extent 用连续段代替间接块树；树按逻辑块索引。</li><li>空洞是未被覆盖的逻辑范围，不必占位图。</li><li>追加式布局是 LFS 的缺口。</li><li>出处：Mathur et al., OLS 2007；Linux <code>Documentation/filesystems/ext4/</code>；<em>OSTEP</em> 对 extent 的对照。</li></ul>',9))])}const _=o(p,[["render",A]]);export{T as __pageData,_ as default};
